/** Public production deployments are synthetic-only unless explicitly opted out. */
export function isDemoMode() {
  const configured = process.env.DEMO_MODE?.trim().toLowerCase();
  if (["1", "true", "on", "yes"].includes(configured ?? "")) return true;
  if (["0", "false", "off", "no"].includes(configured ?? "")) return false;
  return process.env.NODE_ENV === "production";
}
import { NextResponse } from "next/server";
import { extractPdfPages } from "@/lib/pdf-ingestion";
import { isDemoMode } from "@/lib/demo-mode";

export const runtime = "nodejs";
const MAX_PDF_BYTES = 10 * 1024 * 1024;

export async function POST(request: Request) {
  if (isDemoMode()) return NextResponse.json({ error: "PDF ingestion is disabled in synthetic demo mode" }, { status: 403 });
  try {
    const form = await request.formData();
    const file = form.get("file");
    if (!(file instanceof File)) {
      return NextResponse.json({ error: "Upload a PDF in the 'file' field" }, { status: 400 });
    }
    if (file.size > MAX_PDF_BYTES) {
      return NextResponse.json({ error: "PDF exceeds the 10MB limit" }, { status: 413 });
    }
    if (file.type && file.type !== "application/pdf") {
      return NextResponse.json({ error: "File must have PDF content type" }, { status: 415 });
    }
    const pages = await extractPdfPages(new Uint8Array(await file.arrayBuffer()));
    return NextResponse.json({ pages });
  } catch (error) {
  const message =
    error instanceof Error ? error.message : "PDF ingestion failed";

  if (process.env.NODE_ENV === "development") {
    console.error("[PDF DEBUG]", {
      name: error instanceof Error ? error.name : typeof error,
      message,
    });
  }

  const clientError = /empty|limit|not a PDF/i.test(message);

  return NextResponse.json(
    { error: clientError ? message : "PDF could not be read" },
    { status: clientError ? 400 : 422 }
  );
  }
}
import { NextResponse } from "next/server";
import { z } from "zod";
import { investigate } from "@/lib/investigation";
import { isDemoMode } from "@/lib/demo-mode";
import { ensureTracing, flushTracing, tracedWorkflow } from "@/lib/observability";

export const runtime = "nodejs";
const localHosts = new Set(["localhost", "127.0.0.1", "[::1]"]);
function devDiagnostic(category: string, details: Record<string, unknown> = {}) {
  if (process.env.NODE_ENV === "development") console.warn("[MarginGhost diagnostic]", { category, ...details });
}
function isLocalDevelopmentRequest(request: Request) {
  if (process.env.NODE_ENV !== "development") return false;
  let host = "";
  try { host = new URL(`http://${request.headers.get("host")}`).hostname.toLowerCase(); } catch { return false; }
  if (!host || !localHosts.has(host)) return false;
  const origin = request.headers.get("origin");
  if (!origin) return true;
  try { return localHosts.has(new URL(origin).hostname.toLowerCase()); } catch { return false; }
}
export async function POST(request: Request) {
  let tracing = false;
  try {
    if (isDemoMode()) return NextResponse.json({ error: "Live investigation is disabled in synthetic demo mode" }, { status: 403 });
    if (Number(request.headers.get("content-length") || 0) > 1024 * 1024) return NextResponse.json({ error: "Payload too large; 1MB maximum" }, { status: 413 });
    const mode = process.env.LLM_MODE || "offline";
    if (mode !== "offline" && mode !== "groq_free") return NextResponse.json({ error: "Invalid investigation mode" }, { status: 503 });
    if (mode === "groq_free" && !isLocalDevelopmentRequest(request)) {
      devDiagnostic("local_request_rejected");
      return NextResponse.json({ error: "Live extraction is restricted to local development", ...(process.env.NODE_ENV === "development" ? { diagnostic: { category: "local_request_rejected" } } : {}) }, { status: 403 });
    }
    // Offline requests never initialize a network-backed telemetry client.
    if (mode === "groq_free") tracing = await ensureTracing();
    const payload = await request.json();
    const result = await tracedWorkflow(() => investigate(payload));
    if (result.diagnostic) devDiagnostic(result.diagnostic.category, {
      ...(result.diagnostic.status ? { status: result.diagnostic.status } : {}),
      ...(result.diagnostic.fields ? { fields: result.diagnostic.fields } : {}),
      ...(result.diagnostic.providerCode ? { providerCode: result.diagnostic.providerCode } : {}),
      ...(result.diagnostic.providerType ? { providerType: result.diagnostic.providerType } : {}),
      ...(result.diagnostic.param ? { param: result.diagnostic.param } : {}),
      ...(result.diagnostic.providerKeyword ? { providerKeyword: result.diagnostic.providerKeyword } : {})
    });
    if (process.env.NODE_ENV !== "development" && "diagnostic" in result) {
      const safeResult = Object.fromEntries(Object.entries(result).filter(([key]) => key !== "diagnostic"));
      return NextResponse.json(safeResult);
    }
    return NextResponse.json(result);
  } catch (error) {
    if (error instanceof z.ZodError) return NextResponse.json({ error: "Invalid investigation input", issues: error.issues }, { status: 400 });
    if (error instanceof SyntaxError) return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
    return NextResponse.json({ error: error instanceof Error ? error.message : "Investigation failed" }, { status: 422 });
  } finally {
    try { await flushTracing(tracing); } catch { /* tracing must not affect the audit response */ }
  }
}
import { NextResponse } from "next/server";
import { z } from "zod";
import { auditInputSchema } from "@/lib/schema";
import { auditDocuments } from "@/lib/audit";
import { ensureTracing, tracedParse, tracedAudit, tracedWorkflow, flushTracing } from "@/lib/observability";
export const runtime = "nodejs";
export async function POST(request: Request) {
  let tracing = false;
  try {
    if (Number(request.headers.get("content-length") || 0) > 1024 * 1024) {
      return NextResponse.json({ error: "Payload too large; 1MB maximum" }, { status: 413 });
    }
    tracing = await ensureTracing();
    const payload = await request.json();
    const result = await tracedWorkflow(async () => {
      const validated = await tracedParse(() => auditInputSchema.parse(payload));
      return tracedAudit(() => auditDocuments(validated));
    });
    return NextResponse.json(result);
  } catch (error) {
    if (error instanceof z.ZodError) return NextResponse.json({ error: "Invalid document schema", issues: error.issues }, { status: 400 });
    if (error instanceof SyntaxError) return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
    return NextResponse.json({ error: error instanceof Error ? error.message : "Audit failed" }, { status: 422 });
  } finally {
    try { await flushTracing(tracing); } catch (e) { console.error("Trace flush failed", e); }
  }
}
import assert from "node:assert/strict";
import test from "node:test";
import { POST as investigatePost } from "../src/app/api/investigate/route";
import { POST as ingestPost } from "../src/app/api/ingest/pdf/route";
import { extractPdfPages } from "../src/lib/pdf-ingestion";
import { auditDocuments } from "../src/lib/audit";
import { readFile } from "node:fs/promises";

async function fixtureText(name: string) {
  const bytes = new Uint8Array(await readFile(new URL(`../fixtures/live-demo/${name}.pdf`, import.meta.url)));
  return (await extractPdfPages(bytes))[0].text;
}

function audit(unitContract: number, unitPo: number, unitInvoice = 525) {
  return auditDocuments({
    contract: { type: "contract", id: "C-001", supplierId: "S1", currency: "INR", validFrom: "2026-01-01", prices: [{ sku: "SKU-X", unitPrice: unitContract }], evidence: "SKU-X price" },
    purchaseOrder: { type: "purchase_order", id: "P-001", supplierId: "S1", contractId: "C-001", currency: "INR", orderedAt: "2026-09-01", items: [{ sku: "SKU-X", quantity: 400, unitPrice: unitPo }] },
    invoices: [{ type: "invoice", id: "I-001", supplierId: "S1", purchaseOrderId: "P-001", currency: "INR", issuedAt: "2026-09-03", items: [{ sku: "SKU-X", quantity: 400, unitPrice: unitInvoice }] }]
  });
}

test("the three synthetic scenarios match fixture evidence and deterministic outcomes", async () => {
  const [contract, po, invoice, amendment, revisedPo] = await Promise.all([
    fixtureText("contract"), fixtureText("purchase-order"), fixtureText("invoice"), fixtureText("amendment"), fixtureText("purchase-order-amended")
  ]);
  assert.match(contract, /valid 2026-01-01 SKU-X price 480/);
  assert.match(po, /quantity 400 price 480/);
  assert.match(invoice, /quantity 400 price 525/);
  assert.match(amendment, /effective 2026-08-01 SKU-X price 525/);
  assert.match(revisedPo, /quantity 400 price 525/);
  assert.equal(audit(480, 480).totalPotentialOvercharge, 18000);
  const conflict = audit(525, 480);
  assert.equal(conflict.status, "needs_review");
  assert.equal(conflict.totalPotentialOvercharge, 0);
  assert.equal(audit(525, 525).totalPotentialOvercharge, 0);
});

test("demo mode rejects direct HTTP investigation requests before provider setup", async () => {
  const previous = process.env.DEMO_MODE;
  process.env.DEMO_MODE = "true";
  try {
    const response = await investigatePost(new Request("http://example.test/api/investigate", {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ documents: [] })
    }));
    assert.equal(response.status, 403);
    assert.match((await response.json()).error, /disabled in synthetic demo mode/i);
  } finally {
    if (previous === undefined) delete process.env.DEMO_MODE; else process.env.DEMO_MODE = previous;
  }
});

test("demo mode rejects direct multipart PDF ingestion requests before parsing", async () => {
  const previous = process.env.DEMO_MODE;
  process.env.DEMO_MODE = "true";
  try {
    const form = new FormData();
    form.set("file", new File(["not parsed"], "invoice.pdf", { type: "application/pdf" }));
    const response = await ingestPost(new Request("http://example.test/api/ingest/pdf", { method: "POST", body: form }));
    assert.equal(response.status, 403);
    assert.match((await response.json()).error, /PDF ingestion is disabled in synthetic demo mode/i);
  } finally {
    if (previous === undefined) delete process.env.DEMO_MODE; else process.env.DEMO_MODE = previous;
  }
});
:root {
