.stage-mark { position: relative; z-index: 1; width: 17px; height: 17px; display: grid; place-items: center; border: 1px solid #dfe2d9; border-radius: 50%; background: var(--surface); color: var(--forest); font: 9px var(--sans); }
.stage-list li small { grid-column: 2; margin-top: 4px; color: #858e83; font-size: 8px; font-weight: 400; }
.spinner { width: 7px; height: 7px; border: 1px solid #aabaaa; border-top-color: var(--forest); border-radius: 50%; animation: spin .8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.server-note { padding-top: 11px; border-top: 1px solid #eceee7; color: #858d83; font-size: 8px; line-height: 1.55; }
.demo-card { background: #faf9f5; }
.demo-card > p { margin: 8px 0 13px; color: var(--muted); font-size: 10px; line-height: 1.55; }
.demo-actions { display: grid; gap: 6px; }
.demo-actions button { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 9px 10px; border: 1px solid var(--line); border-radius: 4px; background: #fffefa; color: #48564a; text-align: left; font-size: 9px; transition: border-color .16s ease, background .16s ease; }
.demo-actions button:hover { border-color: #c4d1c3; background: #f5f8f3; }
.demo-actions button span { color: #7c857a; font-size: 8px; }
.demo-foot { margin-top: 10px; color: #979c94; font-size: 8px; line-height: 1.5; }
.deployment-note { margin-top: 13px; padding: 10px 12px; border: 1px solid #e8dcc3; border-radius: 5px; background: #fcf7eb; color: #765c2d; font-size: 9px; line-height: 1.5; }

.demo-section { padding: 20px 0 8px; }
.section-heading { align-items: end; margin-bottom: 15px; }
.section-heading h2 { font-size: 29px; }
.section-heading > p { max-width: 300px; margin: 0 0 2px; color: var(--muted); font-size: 10px; line-height: 1.5; }
.scenario-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 11px; }
.scenario-card { min-width: 0; min-height: 197px; display: flex; flex-direction: column; align-items: flex-start; padding: 17px 17px 14px; border: 1px solid var(--line); border-radius: 7px; background: var(--surface); color: var(--ink); text-align: left; transition: border-color .17s ease, background .17s ease, transform .17s ease; }
.scenario-card:hover { transform: translateY(-2px); border-color: #b9c8b8; }
.scenario-card.selected { border-color: #69856c; background: #f8fbf6; }
.scenario-index { color: #858e83; font-size: 8px; }
.scenario-card > strong { margin-top: 20px; color: var(--forest); font: 500 31px/1 var(--serif); letter-spacing: -.035em; }
.scenario-review > strong { color: #805f2a; font-size: 26px; }
.scenario-title { margin-top: 5px; color: #344137; font-size: 11px; font-weight: 600; }
.scenario-copy { max-width: 260px; margin-top: 6px; color: var(--muted); font-size: 9px; line-height: 1.5; }
.scenario-link { display: flex; justify-content: space-between; width: 100%; margin-top: auto; padding-top: 13px; border-top: 1px solid #eceee7; color: #536d57; font-size: 8px; font-weight: 600; }
.scenario-link b { font-size: 11px; font-weight: 500; }
.demo-disclosure { display: flex; align-items: flex-start; gap: 9px; margin-top: 12px; padding: 10px 11px; border: 1px solid #e4e7dc; border-radius: 5px; background: #f9f9f4; color: #71796e; font-size: 9px; line-height: 1.5; }
.demo-disclosure strong { color: #465b48; }
.demo-disclosure-mark { width: 15px; height: 15px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #b9c2b5; border-radius: 50%; color: #6a7b68; font: 600 9px var(--serif); }

.results { margin-top: 22px; scroll-margin-top: 18px; }
.result-banner { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; padding: 21px 23px; border: 1px solid; border-radius: 8px; }
.complete-banner { border-color: #d8e3d6; background: #f0f5ee; }
.review-banner { border-color: #e9dbbd; background: #fcf6e9; }
.result-banner h2 { margin: 6px 0 5px; color: var(--ink); font: 500 28px/1.05 var(--serif); letter-spacing: -.025em; }
.result-banner p { max-width: 640px; margin: 0; color: #687368; font-size: 10px; line-height: 1.55; }
.status-chip { flex: 0 0 auto; padding: 6px 8px; border: 1px solid #d2dfd1; border-radius: 3px; background: #fffe; color: #4f6a52; font-size: 8px; font-weight: 700; letter-spacing: .06em; }
.review-banner .status-chip { border-color: #ead8b3; color: #815d23; }
.result-demo-tag { color: #658168; }
.review-explainer { display: grid; gap: 4px; padding: 11px 14px; border: 1px solid #ead8b4; border-top: 0; background: #fcf5e7; color: #795c2a; font-size: 10px; }
.review-explainer span { color: #806f51; line-height: 1.5; }
.metric-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; margin: 11px 0; }
.metric-card { min-width: 0; padding: 14px 15px; border: 1px solid var(--line); border-radius: 6px; background: var(--surface); }
.metric-card span, .metric-card small { display: block; color: #7c867b; font-size: 8px; }
.metric-card strong { display: block; overflow-wrap: anywhere; margin: 9px 0 4px; color: #28372c; font: 500 28px/1 var(--serif); letter-spacing: -.025em; }
.metric-primary strong { color: var(--forest); font-size: 36px; }
.review-banner ~ .metric-grid .metric-primary strong { color: #775a2b; font-size: 27px; }
.metric-card small { color: #91988f; font-size: 8px; line-height: 1.4; }
.findings-card, .evidence-card { margin-top: 11px; padding: 19px 21px; }
.findings-card .section-head h2, .evidence-card h2 { font-size: 23px; }
.finding-row { margin-top: 14px; padding: 14px 0 4px; border-top: 1px solid #eceee8; }
.finding-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.finding-head > strong { font-size: 10px; }
.finding-head > strong span { color: #aeb4ab; }
.finding-tag { padding: 5px 7px; border-radius: 3px; background: #f8f0df; color: #805e25; font-size: 7px; font-weight: 700; letter-spacing: .04em; }
.review-tag { background: #f8eeeb; color: #8a4e43; }
.finding-row > p { margin: 8px 0 11px; color: #6e786d; font-size: 9px; line-height: 1.5; }
.comparison { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; padding: 11px; border: 1px solid #eceee8; border-radius: 5px; background: #fafaf6; }
.comparison > div { min-width: 0; padding: 2px 3px; }
.comparison small { display: block; margin-bottom: 5px; color: #858e83; font-size: 8px; }
.comparison strong { color: #354238; font-size: 10px; overflow-wrap: anywhere; }
.comparison > b { display: none; }
.line-total { border-left: 1px solid #e2e6dc; padding-left: 11px !important; }
.line-total strong { color: var(--forest); }
.review-empty { display: grid; gap: 5px; margin-top: 14px; padding: 14px; border: 1px solid #eadfc8; border-radius: 5px; background: #fcf7eb; color: #725a31; font-size: 10px; }
.review-empty span { color: #847456; font-size: 9px; }
.zero-findings { display: flex; align-items: flex-start; gap: 10px; margin-top: 14px; padding: 14px 0 1px; border-top: 1px solid #eceee8; }
.zero-check { width: 22px; height: 22px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #d8e3d6; border-radius: 50%; background: #f0f5ee; color: var(--forest); font-size: 11px; }
.zero-findings strong { font-size: 10px; }
.zero-findings p { margin: 4px 0 0; color: #818b80; font-size: 9px; line-height: 1.5; }
.warnings-box { margin-top: 11px; }
.evidence-toolbar { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; }
.evidence-toolbar p { margin: 5px 0 0; color: #858e83; font-size: 9px; line-height: 1.5; }
.source-count { padding: 6px 8px; border: 1px solid var(--line); border-radius: 99px; color: #747e73; font-size: 8px; white-space: nowrap; }
.search-box { min-height: 34px; display: flex; align-items: center; gap: 7px; padding: 0 9px; border: 1px solid var(--line); border-radius: 5px; background: #fff; color: #798278; }
.search-box input { width: 165px; min-width: 0; border: 0; outline: 0; background: transparent; color: var(--ink); font-size: 9px; }
.search-box input::placeholder { color: #9ba198; }
.evidence-list { margin-top: 13px; border-top: 1px solid #eceee8; }
.source-group { border-bottom: 1px solid #eceee8; }
.source-group summary { display: flex; align-items: center; gap: 10px; min-height: 55px; cursor: pointer; list-style: none; }
.source-group summary::-webkit-details-marker { display: none; }
.source-doc-mark { width: 25px; height: 27px; }
.source-doc-title { display: grid; gap: 2px; min-width: 0; }
.source-doc-title strong { color: #344137; font-size: 9px; }
.source-doc-title small { color: #8d958b; font-size: 8px; }
.source-pages { margin-left: auto; color: #858e83; font-size: 8px; letter-spacing: .02em; text-transform: none; }
.source-chevron { margin-left: 5px; color: #6c796d; font-size: 14px; transition: transform .15s ease; }
.source-group[open] .source-chevron { transform: rotate(180deg); }
.source-excerpts { padding: 0 0 8px 35px; }
.evidence-item { padding: 10px 0; border-top: 1px solid #f0f1eb; }
.evidence-meta { display: flex; flex-wrap: wrap; gap: 11px; color: #8c958a; font-size: 7px; letter-spacing: .055em; }
.evidence-item blockquote { margin: 6px 0 0; color: #4b574d; font: 10px/1.65 ui-monospace, SFMono-Regular, Consolas, monospace; overflow-wrap: anywhere; }
.empty-evidence { padding: 16px 0; color: #858e83; font-size: 9px; }
.disclaimer { padding: 12px 0 8px; color: #858e83; text-align: center; font-size: 8px; }
.method-note { display: flex; align-items: baseline; gap: 18px; margin: 23px 0 19px; padding: 14px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.method-note p { max-width: 720px; margin: 0; color: #70796f; font-size: 9px; line-height: 1.55; }
footer { display: flex; justify-content: space-between; gap: 14px; padding: 20px 0 27px; color: #858e83; font-size: 8px; }
footer > span:first-child { color: #59655b; font-weight: 700; }

@media (max-width: 900px) {
  .shell { width: min(100% - 42px, 760px); }
  .workspace { grid-template-columns: minmax(0, 1fr); }
  .side-column { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .demo-section { padding-top: 13px; }
}
@media (max-width: 640px) {
  .shell { width: calc(100% - 32px); }
  .topbar { min-height: 61px; gap: 10px; }

